  add('dress.none', { ja: 'まだ持っていません。ガチャやショップで集めよう！', en: 'Nothing owned yet — try the gacha or the shop!', zh: '还没有拥有。去扭蛋或商店收集吧！', ko: '아직 없어요. 뽑기나 상점에서 모아 봐요!', es: 'Aún no tienes nada: ¡prueba el gacha o la tienda!', fr: 'Rien pour l\'instant — essaie le gacha ou la boutique !', pt: 'Nada ainda — tente o gacha ou a loja!', de: 'Noch nichts — probier das Gacha oder den Shop!', hi: 'अभी कुछ नहीं — गाचा या दुकान आज़माएँ!', ar: 'لا شيء بعد — جرّب الغاتشا أو المتجر!', ru: 'Пока ничего нет — загляните в гачу или магазин!', 'zh-TW': '還沒有任何道具，去扭蛋或商店收集吧！', id: 'Belum punya apa-apa — coba gacha atau toko!', tr: 'Henüz hiçbir şey yok — gacha\'yı ya da mağazayı dene!' });
